import React, { useState, useEffect } from "react";

function Leaderboard() {
  const [roomId] = useState(() => {
    const saved = localStorage.getItem("leetcode-room-id");
    if (saved) return saved;
    const newId = Math.random().toString(36).substring(2, 10);
    localStorage.setItem("leetcode-room-id", newId);
    return newId;
  });

  const [username, setUsername] = useState("");
  const [data, setData] = useState(() => {
    const saved = localStorage.getItem(`room-${roomId}`);
    return saved ? JSON.parse(saved) : [];
  });
  const [loading, setLoading] = useState(false);

  const handleAddUser = async () => {
    const name = username.trim();
    if (!name) return;

    setLoading(true);

    const query = {
      query: `
        query userSessionProgress($username: String!) {
          matchedUser(username: $username) {
            submitStats {
              acSubmissionNum {
                difficulty
                count
              }
            }
          }
          userContestRanking(username: $username) {
            rating
          }
        }
      `,
      variables: { username: name },
    };

    try {
      const res = await fetch("http://localhost:4000/api/leetcode", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(query),
      });

      const json = await res.json();
      const user = json.data.matchedUser;
      const rating = json.data.userContestRanking?.rating || "N/A";
      const acStats = user?.submitStats?.acSubmissionNum || [];

      const getCount = (difficulty) =>
        acStats.find((x) => x.difficulty === difficulty)?.count || 0;

      const problemsSolved = getCount("All");
      const easy = getCount("Easy");
      const medium = getCount("Medium");
      const hard = getCount("Hard");

      const newUser = {
        name,
        problemsSolved,
        easy,
        medium,
        hard,
        contestRating: rating,
      };

      const updated = [...data.filter(u => u.name !== name), newUser].sort(
        (a, b) => b.problemsSolved - a.problemsSolved
      );

      setData(updated);
      localStorage.setItem(`room-${roomId}`, JSON.stringify(updated));
      setUsername("");
    } catch (error) {
      console.error("Error fetching user:", error);
    }

    setLoading(false);
  };

  const handleDelete = (nameToDelete) => {
    const updated = data.filter((user) => user.name !== nameToDelete);
    setData(updated);
    localStorage.setItem(`room-${roomId}`, JSON.stringify(updated));
  };

  return (
    <div className="bg-black min-h-screen text-white px-4 py-8">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold">Jeet_ki_tyaari - Room ID: {roomId}</h1>
        </div>

        <div className="mb-4">
          <input
            type="text"
            placeholder="Enter your LeetCode username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            className="border border-gray-700 bg-gray-800 text-white p-2 rounded w-full"
          />
          <button
            onClick={handleAddUser}
            className="mt-2 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
          >
            Join Room
          </button>
        </div>

        {loading && <p className="text-center text-lg">Loading...</p>}

        {data.length > 0 && (
          <table className="w-full text-left text-sm mt-6">
            <thead className="text-gray-400 border-b border-gray-600">
              <tr>
                <th className="py-2">Rank</th>
                <th>Name</th>
                <th>Total</th>
                <th className="text-green-500">Easy</th>
                <th className="text-yellow-500">Medium</th>
                <th className="text-red-500">Hard</th>
                <th>Rating</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {data.map((user, index) => (
                <tr
                  key={index}
                  className={`border-b border-gray-700`}
                >
                  <td className="py-3">{index + 1}</td>
                  <td className="font-medium text-blue-400">{user.name}</td>
                  <td>{user.problemsSolved}</td>
                  <td className="text-green-500">{user.easy}</td>
                  <td className="text-yellow-500">{user.medium}</td>
                  <td className="text-red-500">{user.hard}</td>
                  <td>{user.contestRating}</td>
                  <td>
                    <button
                      onClick={() => handleDelete(user.name)}
                      className="text-red-500 hover:underline"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

export default Leaderboard;
